export interface WindowConfig {
  readonly limit: number;
  readonly windowMs: number;
}

export interface Decision {
  readonly allowed: boolean;
  readonly remaining: number;
  readonly retryAfterMs: number;
}

export class SlidingWindowLimiter {
  private readonly hits = new Map<string, Array<number>>();

  constructor(private readonly config: WindowConfig) {}

  check(key: string, nowMs: number): Decision {
    const cutoff = nowMs - this.config.windowMs;
    const entries = this.hits.get(key) ?? [];
    const active = entries.filter((ts) => ts >= cutoff);

    if (active.length >= this.config.limit) {
      this.hits.set(key, active);
      const oldest = active[0] ?? nowMs;
      return {
        allowed: false,
        remaining: 0,
        retryAfterMs: Math.max(0, oldest + this.config.windowMs - nowMs),
      };
    }

    const next = [...active, nowMs];
    this.hits.set(key, next);
    return {
      allowed: true,
      remaining: this.config.limit - next.length,
      retryAfterMs: 0,
    };
  }
}

