import { describe, expect, it } from "bun:test";
import { SlidingWindowLimiter } from "../src/limiter";

describe("SlidingWindowLimiter", () => {
  it("allows requests within the configured limit", () => {
    const limiter = new SlidingWindowLimiter({ limit: 2, windowMs: 1000 });
    expect(limiter.check("alpha", 100)).toEqual({ allowed: true, remaining: 1, retryAfterMs: 0 });
    expect(limiter.check("alpha", 200)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
  });

  it("blocks requests exceeding the limit inside the active window", () => {
    const limiter = new SlidingWindowLimiter({ limit: 2, windowMs: 1000 });
    limiter.check("alpha", 100);
    limiter.check("alpha", 200);
    expect(limiter.check("alpha", 500)).toEqual({ allowed: false, remaining: 0, retryAfterMs: 600 });
  });

  it("expires requests strictly older than the window", () => {
    const limiter = new SlidingWindowLimiter({ limit: 1, windowMs: 1000 });
    expect(limiter.check("alpha", 100).allowed).toBe(true);
    expect(limiter.check("alpha", 1101)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
  });

  it("tracks keys independently", () => {
    const limiter = new SlidingWindowLimiter({ limit: 1, windowMs: 1000 });
    expect(limiter.check("alpha", 100).allowed).toBe(true);
    expect(limiter.check("beta", 100).allowed).toBe(true);
  });
});

