import { describe, expect, it } from "bun:test";
import { SlidingWindowLimiter } from "../src/limiter";

describe("SlidingWindowLimiter boundary oracle", () => {
  it("expires a hit at exact nowMs - windowMs", () => {
    const limiter = new SlidingWindowLimiter({ limit: 1, windowMs: 1000 });
    expect(limiter.check("alpha", 1000)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
    expect(limiter.check("alpha", 2000)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
  });

  it("still blocks 1ms before expiry with retryAfterMs 1", () => {
    const limiter = new SlidingWindowLimiter({ limit: 1, windowMs: 1000 });
    expect(limiter.check("alpha", 1000).allowed).toBe(true);
    expect(limiter.check("alpha", 1999)).toEqual({ allowed: false, remaining: 0, retryAfterMs: 1 });
  });

  it("evicts only expired hits at the exact boundary in multi-hit windows", () => {
    const limiter = new SlidingWindowLimiter({ limit: 2, windowMs: 1000 });
    expect(limiter.check("alpha", 1000)).toEqual({ allowed: true, remaining: 1, retryAfterMs: 0 });
    expect(limiter.check("alpha", 1500)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
    expect(limiter.check("alpha", 2000)).toEqual({ allowed: true, remaining: 0, retryAfterMs: 0 });
    expect(limiter.check("alpha", 2000)).toEqual({ allowed: false, remaining: 0, retryAfterMs: 500 });
  });

  it("keeps key isolation intact", () => {
    const limiter = new SlidingWindowLimiter({ limit: 1, windowMs: 1000 });
    expect(limiter.check("alpha", 1000).allowed).toBe(true);
    expect(limiter.check("beta", 1000).allowed).toBe(true);
    expect(limiter.check("alpha", 1999).allowed).toBe(false);
    expect(limiter.check("beta", 2000).allowed).toBe(true);
  });
});
